-- V38__assistant_chatbot.sql
-- JanNet Sahayak, the in-app assistant (chatbot) v1 - feature plan
-- plans/2026-10-15_PROJECT_DESCRIPTION_AND_FEATURE_PLAN.md, Feature A.
--
--  * assistant_sessions / assistant_messages: every conversation is logged
--    (who, when, which intent and which tools answered it). The text stored
--    is the REDACTED text (phone numbers, e-mail addresses, the user's own
--    name removed by the backend before saving). Kept 90 days, then deleted
--    by the backend's daily retention job:
--        DELETE FROM assistant_sessions
--         WHERE last_message_at < (UTC_TIMESTAMP() - INTERVAL 90 DAY);
--    (assistant_messages rows go with their session: ON DELETE CASCADE.)
--    A user's sessions are also deleted when the user erases the account.
--  * help_articles: short help texts written by the team, one row per
--    article and language (EN, HI, MR, BN, TA, TE, KN - the app's seven
--    languages). The assistant answers FAQ questions only from these rows.
--    keywords: comma-separated phrases used to match a question; EN and HI
--    rows also carry common Hinglish (romanised Hindi) phrases.
--
-- Seeded: 20 articles x 7 languages. Translations other than EN/HI are
-- machine-assisted and need native review (same known limit as the app's
-- interface translations).

CREATE TABLE assistant_sessions (
    session_id       BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    public_id        CHAR(36)        NOT NULL,
    user_id          BIGINT UNSIGNED NOT NULL,
    language         VARCHAR(2)      NOT NULL DEFAULT 'EN',
    message_count    INT             NOT NULL DEFAULT 0,
    created_at       TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_message_at  TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT uq_assistant_sessions_public_id UNIQUE (public_id),
    CONSTRAINT fk_assistant_sessions_user
        FOREIGN KEY (user_id) REFERENCES users (user_id)
        ON DELETE CASCADE,
    CONSTRAINT chk_assistant_sessions_language CHECK (
        language IN ('EN', 'HI', 'MR', 'BN', 'TA', 'TE', 'KN')
    ),
    CONSTRAINT chk_assistant_sessions_message_count CHECK (message_count >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci
  COMMENT='JanNet Sahayak conversations (kept 90 days)';

CREATE INDEX idx_assistant_sessions_user ON assistant_sessions (user_id, last_message_at);
CREATE INDEX idx_assistant_sessions_last_message ON assistant_sessions (last_message_at);

CREATE TABLE assistant_messages (
    message_id     BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    session_id     BIGINT UNSIGNED NOT NULL,
    sender         VARCHAR(10)     NOT NULL,
    message_text   VARCHAR(2000)   NOT NULL,
    intent         VARCHAR(40)     NULL,
    answer_source  VARCHAR(20)     NULL,
    tools_used     VARCHAR(255)    NULL,
    complaint_id   BIGINT UNSIGNED NULL,
    created_at     TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_assistant_messages_session
        FOREIGN KEY (session_id) REFERENCES assistant_sessions (session_id)
        ON DELETE CASCADE,
    CONSTRAINT fk_assistant_messages_complaint
        FOREIGN KEY (complaint_id) REFERENCES complaints (complaint_id)
        ON DELETE SET NULL,
    CONSTRAINT chk_assistant_messages_sender CHECK (sender IN ('USER', 'ASSISTANT')),
    -- RULE: answered from the user's own data by a fixed rule; ARTICLE: from a
    -- help article; AI: worded by Gemini from those sources; FALLBACK: the
    -- assistant could not answer and offered the menu.
    CONSTRAINT chk_assistant_messages_answer_source CHECK (
        answer_source IS NULL OR answer_source IN ('RULE', 'ARTICLE', 'AI', 'FALLBACK')
    )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci
  COMMENT='JanNet Sahayak messages, redacted text only';

CREATE INDEX idx_assistant_messages_session ON assistant_messages (session_id, message_id);
CREATE INDEX idx_assistant_messages_created ON assistant_messages (created_at);

CREATE TABLE help_articles (
    article_id   BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    slug         VARCHAR(60)     NOT NULL,
    language     VARCHAR(2)      NOT NULL,
    topic        VARCHAR(20)     NOT NULL,
    title        VARCHAR(200)    NOT NULL,
    body         VARCHAR(2000)   NOT NULL,
    keywords     VARCHAR(1000)   NOT NULL DEFAULT '',
    sort_order   INT             NOT NULL DEFAULT 0,
    is_active    BOOLEAN         NOT NULL DEFAULT TRUE,
    created_at   TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at   TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

    CONSTRAINT uq_help_articles_slug_language UNIQUE (slug, language),
    CONSTRAINT chk_help_articles_language CHECK (
        language IN ('EN', 'HI', 'MR', 'BN', 'TA', 'TE', 'KN')
    ),
    CONSTRAINT chk_help_articles_topic CHECK (topic IN ('REPORT', 'TRACK', 'AFTER', 'ACCOUNT')),
    CONSTRAINT chk_help_articles_slug CHECK (REGEXP_LIKE(slug, '^[a-z0-9-]+$', 'c'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci
  COMMENT='JanNet Sahayak help articles, one row per article and language';

CREATE INDEX idx_help_articles_language ON help_articles (language, is_active, sort_order);

-- Seed: 20 articles x 7 languages.
