INSERT INTO help_articles (slug, language, topic, title, body, keywords, sort_order) VALUES
('how-to-report', 'EN', 'REPORT', 'How do I report a problem?', 'Open the Submit tab. 1. Take a photo of the problem or choose one from your gallery. 2. Write a short description: what it is and how long it has been there. 3. Confirm on the map where the problem is. 4. Press Submit. You get a reference number like JN-2026-000123 to track it.', 'how to report, how do i report, how can i report, how to complain, how do i complain, report a problem, new complaint, file a complaint, submit complaint, register complaint, shikayat kaise, shikayat darj, complaint kaise kare, report kaise kare, shikayat karni hai', 10),
('how-to-report', 'HI', 'REPORT', 'समस्या की शिकायत कैसे करें?', 'दर्ज करें टैब खोलें। 1. समस्या की फ़ोटो लें या गैलरी से चुनें। 2. छोटा विवरण लिखें: समस्या क्या है और कब से है। 3. नक्शे पर पुष्टि करें कि समस्या कहाँ है। 4. सबमिट दबाएँ। आपको JN-2026-000123 जैसा संदर्भ नंबर मिलेगा, जिससे आप शिकायत देख सकते हैं।', 'शिकायत कैसे, शिकायत दर्ज, नई शिकायत, रिपोर्ट कैसे, शिकायत करनी है, shikayat kaise, shikayat darj, complaint kaise kare, report kaise kare', 10),
('how-to-report', 'MR', 'REPORT', 'समस्येची तक्रार कशी करावी?', 'सबमिट टॅब उघडा. 1. समस्येचा फोटो घ्या किंवा गॅलरीतून निवडा. 2. थोडक्यात वर्णन लिहा: समस्या काय आहे आणि केव्हापासून आहे. 3. नकाशावर समस्या कुठे आहे ते निश्चित करा. 4. सबमिट दाबा. तक्रार पाहण्यासाठी तुम्हाला JN-2026-000123 सारखा संदर्भ क्रमांक मिळेल.', 'तक्रार कशी, तक्रार नोंदवा, नवीन तक्रार, रिपोर्ट कसा', 10),
('how-to-report', 'BN', 'REPORT', 'কীভাবে সমস্যার অভিযোগ করব?', 'জমা দিন ট্যাব খুলুন। 1. সমস্যার ছবি তুলুন বা গ্যালারি থেকে বেছে নিন। 2. ছোট বিবরণ লিখুন: সমস্যাটি কী এবং কতদিন ধরে আছে। 3. মানচিত্রে নিশ্চিত করুন সমস্যাটি কোথায়। 4. জমা দিন চাপুন। অভিযোগ দেখার জন্য আপনি JN-2026-000123 এর মতো একটি রেফারেন্স নম্বর পাবেন।', 'কীভাবে অভিযোগ, অভিযোগ জানান, নতুন অভিযোগ, রিপোর্ট', 10),
('how-to-report', 'TA', 'REPORT', 'ஒரு பிரச்சினையை எப்படிப் புகார் செய்வது?', 'சமர்ப்பி தாவலைத் திறக்கவும். 1. பிரச்சினையின் புகைப்படம் எடுக்கவும் அல்லது கேலரியிலிருந்து தேர்ந்தெடுக்கவும். 2. சிறு விளக்கம் எழுதவும்: அது என்ன, எவ்வளவு காலமாக உள்ளது. 3. பிரச்சினை எங்கே உள்ளது என்பதை வரைபடத்தில் உறுதிப்படுத்தவும். 4. சமர்ப்பி அழுத்தவும். புகாரைப் பின்தொடர JN-2026-000123 போன்ற குறிப்பு எண் கிடைக்கும்.', 'எப்படிப் புகார், புகார் செய்ய, புதிய புகார், புகாரளி', 10),
('how-to-report', 'TE', 'REPORT', 'సమస్యపై ఫిర్యాదు ఎలా చేయాలి?', 'సమర్పించు ట్యాబ్ తెరవండి. 1. సమస్య ఫోటో తీయండి లేదా గ్యాలరీ నుండి ఎంచుకోండి. 2. చిన్న వివరణ రాయండి: అది ఏమిటి, ఎప్పటి నుండి ఉంది. 3. సమస్య ఎక్కడ ఉందో మ్యాప్‌లో నిర్ధారించండి. 4. సమర్పించు నొక్కండి. ఫిర్యాదును ట్రాక్ చేయడానికి JN-2026-000123 వంటి రిఫరెన్స్ నంబర్ వస్తుంది.', 'ఫిర్యాదు ఎలా, ఫిర్యాదు చేయాలి, కొత్త ఫిర్యాదు, నివేదించు', 10),
('how-to-report', 'KN', 'REPORT', 'ಸಮಸ್ಯೆಯ ಬಗ್ಗೆ ದೂರು ನೀಡುವುದು ಹೇಗೆ?', 'ಸಲ್ಲಿಸಿ ಟ್ಯಾಬ್ ತೆರೆಯಿರಿ. 1. ಸಮಸ್ಯೆಯ ಫೋಟೋ ತೆಗೆಯಿರಿ ಅಥವಾ ಗ್ಯಾಲರಿಯಿಂದ ಆಯ್ಕೆಮಾಡಿ. 2. ಚಿಕ್ಕ ವಿವರಣೆ ಬರೆಯಿರಿ: ಅದು ಏನು, ಎಷ್ಟು ದಿನಗಳಿಂದ ಇದೆ. 3. ಸಮಸ್ಯೆ ಎಲ್ಲಿದೆ ಎಂದು ನಕ್ಷೆಯಲ್ಲಿ ಖಚಿತಪಡಿಸಿ. 4. ಸಲ್ಲಿಸಿ ಒತ್ತಿರಿ. ದೂರನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಲು JN-2026-000123 ನಂತಹ ಉಲ್ಲೇಖ ಸಂಖ್ಯೆ ಸಿಗುತ್ತದೆ.', 'ದೂರು ಹೇಗೆ, ದೂರು ನೀಡಲು, ಹೊಸ ದೂರು, ವರದಿ ಮಾಡಿ', 10),
('photo-tips', 'EN', 'REPORT', 'Tips for a good photo', 'Take the photo in daylight, close enough to show the problem clearly. Hold the phone steady: blurry or very small photos (below 480 pixels) are refused and you are asked to take them again. A photo taken in the app keeps its location, which helps the office find the place.', 'photo, picture, image, camera, blurry, retake, photo tips, good photo, photo kaise, photo reject, tasveer', 20),
('photo-tips', 'HI', 'REPORT', 'अच्छी फ़ोटो कैसे लें', 'फ़ोटो दिन की रोशनी में और इतने पास से लें कि समस्या साफ़ दिखे। फ़ोन स्थिर रखें: धुंधली या बहुत छोटी फ़ोटो (480 पिक्सेल से कम) स्वीकार नहीं होती और दोबारा लेने को कहा जाता है। ऐप में ली गई फ़ोटो में जगह की जानकारी रहती है, जिससे कार्यालय को जगह ढूँढने में मदद मिलती है।', 'फ़ोटो, फोटो, तस्वीर, कैमरा, धुंधली, दोबारा फ़ोटो, photo kaise, photo reject, tasveer', 20),
('photo-tips', 'MR', 'REPORT', 'चांगला फोटो कसा घ्यावा', 'फोटो दिवसाच्या उजेडात आणि समस्या स्पष्ट दिसेल इतक्या जवळून घ्या. फोन स्थिर धरा: अस्पष्ट किंवा खूप लहान फोटो (480 पिक्सेलपेक्षा कमी) स्वीकारले जात नाहीत आणि पुन्हा घेण्यास सांगितले जाते. अ‍ॅपमध्ये घेतलेल्या फोटोमध्ये ठिकाणाची माहिती राहते, त्यामुळे कार्यालयाला जागा शोधायला मदत होते.', 'फोटो, छायाचित्र, कॅमेरा, अस्पष्ट, पुन्हा फोटो', 20),
('photo-tips', 'BN', 'REPORT', 'ভালো ছবি তোলার টিপস', 'দিনের আলোয় এবং সমস্যাটি পরিষ্কার দেখা যায় এমন কাছ থেকে ছবি তুলুন। ফোন স্থির রাখুন: ঝাপসা বা খুব ছোট ছবি (480 পিক্সেলের কম) গ্রহণ করা হয় না এবং আবার তুলতে বলা হয়। অ্যাপে তোলা ছবিতে জায়গার তথ্য থাকে, যা অফিসকে জায়গাটি খুঁজে পেতে সাহায্য করে।', 'ছবি, ফটো, ক্যামেরা, ঝাপসা, আবার ছবি', 20),
('photo-tips', 'TA', 'REPORT', 'நல்ல புகைப்படத்திற்கான குறிப்புகள்', 'பகல் வெளிச்சத்தில், பிரச்சினை தெளிவாகத் தெரியும் அளவு அருகில் புகைப்படம் எடுக்கவும். தொலைபேசியை அசையாமல் பிடிக்கவும்: மங்கலான அல்லது மிகச் சிறிய புகைப்படங்கள் (480 பிக்சலுக்குக் குறைவு) ஏற்கப்படாது, மீண்டும் எடுக்கக் கேட்கப்படும். செயலியில் எடுத்த புகைப்படத்தில் இருப்பிடம் சேமிக்கப்படும், இது அலுவலகம் இடத்தைக் கண்டறிய உதவும்.', 'புகைப்படம், படம், கேமரா, மங்கலான, மீண்டும் எடு', 20),
('photo-tips', 'TE', 'REPORT', 'మంచి ఫోటో కోసం సూచనలు', 'పగటి వెలుతురులో, సమస్య స్పష్టంగా కనిపించేంత దగ్గరగా ఫోటో తీయండి. ఫోన్‌ను స్థిరంగా పట్టుకోండి: అస్పష్టమైన లేదా చాలా చిన్న ఫోటోలు (480 పిక్సెల్‌ల కంటే తక్కువ) అంగీకరించబడవు, మళ్లీ తీయమని అడుగుతారు. యాప్‌లో తీసిన ఫోటోలో స్థలం సమాచారం ఉంటుంది, ఇది కార్యాలయం ఆ స్థలాన్ని కనుగొనడానికి సహాయపడుతుంది.', 'ఫోటో, చిత్రం, కెమెరా, అస్పష్టం, మళ్లీ ఫోటో', 20),
('photo-tips', 'KN', 'REPORT', 'ಉತ್ತಮ ಫೋಟೋಗಾಗಿ ಸಲಹೆಗಳು', 'ಹಗಲಿನ ಬೆಳಕಿನಲ್ಲಿ, ಸಮಸ್ಯೆ ಸ್ಪಷ್ಟವಾಗಿ ಕಾಣುವಷ್ಟು ಹತ್ತಿರದಿಂದ ಫೋಟೋ ತೆಗೆಯಿರಿ. ಫೋನನ್ನು ಸ್ಥಿರವಾಗಿ ಹಿಡಿಯಿರಿ: ಮಸುಕಾದ ಅಥವಾ ತುಂಬಾ ಚಿಕ್ಕ ಫೋಟೋಗಳನ್ನು (480 ಪಿಕ್ಸೆಲ್‌ಗಿಂತ ಕಡಿಮೆ) ಸ್ವೀಕರಿಸಲಾಗುವುದಿಲ್ಲ, ಮತ್ತೆ ತೆಗೆಯಲು ಕೇಳಲಾಗುತ್ತದೆ. ಆ್ಯಪ್‌ನಲ್ಲಿ ತೆಗೆದ ಫೋಟೋದಲ್ಲಿ ಸ್ಥಳದ ಮಾಹಿತಿ ಇರುತ್ತದೆ, ಇದು ಕಚೇರಿಗೆ ಸ್ಥಳವನ್ನು ಹುಡುಕಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ.', 'ಫೋಟೋ, ಚಿತ್ರ, ಕ್ಯಾಮೆರಾ, ಮಸುಕು, ಮತ್ತೆ ಫೋಟೋ', 20),
('location-help', 'EN', 'REPORT', 'Marking where the problem is', 'The app suggests the place from the photo''s location. Check the pin on the map and answer "Is this the place?". If it is wrong, move the pin, or enter the PIN code and choose your village or town. Choosing the ward is optional: the office checks it.', 'location, map, pin, address, place, ward, village, pin code, wrong location, jagah, location galat, gaon, pata', 30),
('location-help', 'HI', 'REPORT', 'समस्या की जगह कैसे बताएँ', 'ऐप फ़ोटो की लोकेशन से जगह सुझाता है। नक्शे पर पिन देखें और "क्या यही जगह है?" का जवाब दें। ग़लत हो तो पिन खिसकाएँ, या पिन कोड डालकर अपना गाँव या नगर चुनें। वार्ड चुनना ज़रूरी नहीं है: कार्यालय उसकी जाँच करता है।', 'जगह, लोकेशन, नक्शा, पिन, पता, वार्ड, गाँव, पिन कोड, jagah, location galat, gaon, pata', 30),
('location-help', 'MR', 'REPORT', 'समस्येचे ठिकाण कसे सांगावे', 'अ‍ॅप फोटोच्या लोकेशनवरून ठिकाण सुचवते. नकाशावरील पिन तपासा आणि "हीच जागा आहे का?" याचे उत्तर द्या. चुकीचे असल्यास पिन हलवा, किंवा पिन कोड टाकून तुमचे गाव किंवा शहर निवडा. वॉर्ड निवडणे ऐच्छिक आहे: कार्यालय ते तपासते.', 'ठिकाण, जागा, नकाशा, पिन, पत्ता, वॉर्ड, गाव, पिन कोड', 30),
('location-help', 'BN', 'REPORT', 'সমস্যার জায়গা কীভাবে চিহ্নিত করবেন', 'অ্যাপ ছবির লোকেশন থেকে জায়গা প্রস্তাব করে। মানচিত্রে পিন দেখুন এবং "এটাই কি সেই জায়গা?" প্রশ্নের উত্তর দিন। ভুল হলে পিন সরান, অথবা পিন কোড দিয়ে আপনার গ্রাম বা শহর বেছে নিন। ওয়ার্ড বেছে নেওয়া ঐচ্ছিক: অফিস তা যাচাই করে।', 'জায়গা, লোকেশন, মানচিত্র, পিন, ঠিকানা, ওয়ার্ড, গ্রাম, পিন কোড', 30),
('location-help', 'TA', 'REPORT', 'பிரச்சினை உள்ள இடத்தைக் குறிப்பது', 'புகைப்படத்தின் இருப்பிடத்திலிருந்து செயலி இடத்தைப் பரிந்துரைக்கும். வரைபடத்தில் பின்னைச் சரிபார்த்து "இதுதான் இடமா?" என்பதற்குப் பதிலளிக்கவும். தவறாக இருந்தால் பின்னை நகர்த்தவும், அல்லது அஞ்சல் குறியீட்டை உள்ளிட்டு உங்கள் கிராமம் அல்லது நகரத்தைத் தேர்ந்தெடுக்கவும். வார்டைத் தேர்ந்தெடுப்பது விருப்பத்தேர்வு: அலுவலகம் அதைச் சரிபார்க்கும்.', 'இடம், இருப்பிடம், வரைபடம், பின், முகவரி, வார்டு, கிராமம், அஞ்சல் குறியீடு', 30),
('location-help', 'TE', 'REPORT', 'సమస్య ఉన్న స్థలాన్ని గుర్తించడం', 'ఫోటో లొకేషన్ నుండి యాప్ స్థలాన్ని సూచిస్తుంది. మ్యాప్‌లో పిన్‌ను తనిఖీ చేసి "ఇదేనా ఆ స్థలం?" అనే ప్రశ్నకు సమాధానం ఇవ్వండి. తప్పుగా ఉంటే పిన్‌ను జరపండి, లేదా పిన్ కోడ్ నమోదు చేసి మీ గ్రామం లేదా పట్టణాన్ని ఎంచుకోండి. వార్డును ఎంచుకోవడం ఐచ్ఛికం: కార్యాలయం దాన్ని తనిఖీ చేస్తుంది.', 'స్థలం, లొకేషన్, మ్యాప్, పిన్, చిరునామా, వార్డు, గ్రామం, పిన్ కోడ్', 30),
('location-help', 'KN', 'REPORT', 'ಸಮಸ್ಯೆ ಇರುವ ಸ್ಥಳವನ್ನು ಗುರುತಿಸುವುದು', 'ಫೋಟೋದ ಸ್ಥಳದಿಂದ ಆ್ಯಪ್ ಸ್ಥಳವನ್ನು ಸೂಚಿಸುತ್ತದೆ. ನಕ್ಷೆಯಲ್ಲಿ ಪಿನ್ ಪರಿಶೀಲಿಸಿ ಮತ್ತು "ಇದೇ ಸ್ಥಳವೇ?" ಎಂಬುದಕ್ಕೆ ಉತ್ತರಿಸಿ. ತಪ್ಪಾಗಿದ್ದರೆ ಪಿನ್ ಸರಿಸಿ, ಅಥವಾ ಪಿನ್ ಕೋಡ್ ನಮೂದಿಸಿ ನಿಮ್ಮ ಗ್ರಾಮ ಅಥವಾ ಪಟ್ಟಣವನ್ನು ಆಯ್ಕೆಮಾಡಿ. ವಾರ್ಡ್ ಆಯ್ಕೆ ಐಚ್ಛಿಕ: ಕಚೇರಿ ಅದನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ.', 'ಸ್ಥಳ, ಲೊಕೇಶನ್, ನಕ್ಷೆ, ಪಿನ್, ವಿಳಾಸ, ವಾರ್ಡ್, ಗ್ರಾಮ, ಪಿನ್ ಕೋಡ್', 30),
('what-can-report', 'EN', 'REPORT', 'What problems can I report?', 'Public problems such as potholes, overflowing garbage, water leakage, broken street lights, open manholes and illegal construction. Other public problems can be reported too: the Verification Team checks them. Personal disputes and emergencies cannot be handled here; in an emergency call 112.', 'what can i report, which problems, category, types of problems, pothole, garbage, street light, manhole, water leakage, illegal construction, kya report kar sakte, kaun si samasya', 40),
('what-can-report', 'HI', 'REPORT', 'मैं किन समस्याओं की शिकायत कर सकता/सकती हूँ?', 'सार्वजनिक समस्याएँ, जैसे सड़क के गड्ढे, भरा हुआ कूड़ा, पानी का रिसाव, ख़राब स्ट्रीट लाइट, खुले मैनहोल और अवैध निर्माण। अन्य सार्वजनिक समस्याओं की भी शिकायत की जा सकती है: सत्यापन टीम उनकी जाँच करती है। निजी विवाद और आपात स्थिति यहाँ नहीं संभाली जातीं; आपात स्थिति में 112 पर कॉल करें।', 'कौन सी समस्या, किन समस्याओं, श्रेणी, गड्ढा, कूड़ा, स्ट्रीट लाइट, मैनहोल, पानी, अवैध निर्माण, kya report kar sakte, kaun si samasya', 40),
('what-can-report', 'MR', 'REPORT', 'मी कोणत्या समस्यांची तक्रार करू शकतो?', 'सार्वजनिक समस्या, जसे रस्त्यावरील खड्डे, भरलेला कचरा, पाण्याची गळती, बंद पथदिवे, उघडे मॅनहोल आणि अवैध बांधकाम. इतर सार्वजनिक समस्यांचीही तक्रार करता येते: पडताळणी पथक त्या तपासते. वैयक्तिक वाद आणि आणीबाणी येथे हाताळल्या जात नाहीत; आणीबाणीत 112 वर कॉल करा.', 'कोणत्या समस्या, प्रकार, खड्डा, कचरा, पथदिवा, मॅनहोल, पाणी गळती, अवैध बांधकाम', 40),
('what-can-report', 'BN', 'REPORT', 'কোন কোন সমস্যার অভিযোগ করা যায়?', 'জনসাধারণের সমস্যা, যেমন রাস্তার গর্ত, উপচে পড়া আবর্জনা, জলের লিকেজ, খারাপ রাস্তার আলো, খোলা ম্যানহোল এবং অবৈধ নির্মাণ। অন্য জনসাধারণের সমস্যারও অভিযোগ করা যায়: যাচাই দল সেগুলি পরীক্ষা করে। ব্যক্তিগত বিবাদ ও জরুরি অবস্থা এখানে দেখা হয় না; জরুরি অবস্থায় 112-এ ফোন করুন।', 'কোন সমস্যা, ধরন, গর্ত, আবর্জনা, রাস্তার আলো, ম্যানহোল, জল, অবৈধ নির্মাণ', 40),
('what-can-report', 'TA', 'REPORT', 'எந்தப் பிரச்சினைகளைப் புகார் செய்யலாம்?', 'சாலைக் குழிகள், நிரம்பி வழியும் குப்பை, நீர்க் கசிவு, பழுதான தெருவிளக்குகள், திறந்த மேன்ஹோல்கள், சட்டவிரோதக் கட்டுமானம் போன்ற பொதுப் பிரச்சினைகள். பிற பொதுப் பிரச்சினைகளையும் புகார் செய்யலாம்: சரிபார்ப்புக் குழு அவற்றைச் சரிபார்க்கும். தனிப்பட்ட தகராறுகள் மற்றும் அவசரநிலைகள் இங்கு கையாளப்படாது; அவசரநிலையில் 112 அழைக்கவும்.', 'எந்தப் பிரச்சினை, வகை, குழி, குப்பை, தெருவிளக்கு, மேன்ஹோல், நீர்க் கசிவு, கட்டுமானம்', 40),
('what-can-report', 'TE', 'REPORT', 'ఏ సమస్యలపై ఫిర్యాదు చేయవచ్చు?', 'రోడ్డుపై గుంతలు, పొంగిపొర్లుతున్న చెత్త, నీటి లీకేజీ, పాడైన వీధి దీపాలు, తెరిచి ఉన్న మ్యాన్‌హోల్‌లు, అక్రమ నిర్మాణం వంటి ప్రజా సమస్యలు. ఇతర ప్రజా సమస్యలపై కూడా ఫిర్యాదు చేయవచ్చు: ధృవీకరణ బృందం వాటిని తనిఖీ చేస్తుంది. వ్యక్తిగత వివాదాలు, అత్యవసర పరిస్థితులు ఇక్కడ చూడబడవు; అత్యవసరంలో 112కు కాల్ చేయండి.', 'ఏ సమస్యలు, రకం, గుంత, చెత్త, వీధి దీపం, మ్యాన్‌హోల్, నీటి లీకేజీ, అక్రమ నిర్మాణం', 40),
('what-can-report', 'KN', 'REPORT', 'ಯಾವ ಸಮಸ್ಯೆಗಳ ಬಗ್ಗೆ ದೂರು ನೀಡಬಹುದು?', 'ರಸ್ತೆ ಗುಂಡಿಗಳು, ತುಂಬಿ ಹರಿಯುವ ಕಸ, ನೀರಿನ ಸೋರಿಕೆ, ಕೆಟ್ಟ ಬೀದಿ ದೀಪಗಳು, ತೆರೆದ ಮ್ಯಾನ್‌ಹೋಲ್‌ಗಳು ಮತ್ತು ಅಕ್ರಮ ನಿರ್ಮಾಣದಂತಹ ಸಾರ್ವಜನಿಕ ಸಮಸ್ಯೆಗಳು. ಇತರ ಸಾರ್ವಜನಿಕ ಸಮಸ್ಯೆಗಳ ಬಗ್ಗೆಯೂ ದೂರು ನೀಡಬಹುದು: ಪರಿಶೀಲನಾ ತಂಡ ಅವುಗಳನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ. ವೈಯಕ್ತಿಕ ವಿವಾದಗಳು ಮತ್ತು ತುರ್ತು ಪರಿಸ್ಥಿತಿಗಳನ್ನು ಇಲ್ಲಿ ನಿರ್ವಹಿಸಲಾಗುವುದಿಲ್ಲ; ತುರ್ತು ಸಂದರ್ಭದಲ್ಲಿ 112ಕ್ಕೆ ಕರೆ ಮಾಡಿ.', 'ಯಾವ ಸಮಸ್ಯೆ, ವಿಧ, ಗುಂಡಿ, ಕಸ, ಬೀದಿ ದೀಪ, ಮ್ಯಾನ್‌ಹೋಲ್, ನೀರಿನ ಸೋರಿಕೆ, ಅಕ್ರಮ ನಿರ್ಮಾಣ', 40),
('track-complaint', 'EN', 'TRACK', 'How do I track my complaint?', 'Open My Complaints to see every complaint and its current status. Tap one to see its full history. You can also ask me: type your reference number, for example JN-2026-000123. You get an e-mail when the status changes.', 'track, tracking, where is my complaint, my complaint, progress, check status, complaint status, kahan hai, kya hua, status kya hai, meri shikayat', 50),
('track-complaint', 'HI', 'TRACK', 'अपनी शिकायत की स्थिति कैसे देखें?', 'मेरी शिकायतें खोलें, वहाँ हर शिकायत और उसकी अभी की स्थिति दिखती है। पूरा इतिहास देखने के लिए किसी शिकायत पर टैप करें। आप मुझसे भी पूछ सकते हैं: अपना संदर्भ नंबर लिखें, जैसे JN-2026-000123। स्थिति बदलने पर आपको ई-मेल मिलता है।', 'स्थिति, मेरी शिकायत, कहाँ है, क्या हुआ, ट्रैक, शिकायत की स्थिति, kahan hai, kya hua, status kya hai, meri shikayat', 50),
('track-complaint', 'MR', 'TRACK', 'माझ्या तक्रारीची स्थिती कशी पाहावी?', 'माझ्या तक्रारी उघडा, तिथे प्रत्येक तक्रार आणि तिची सध्याची स्थिती दिसते. संपूर्ण इतिहास पाहण्यासाठी तक्रारीवर टॅप करा. तुम्ही मलाही विचारू शकता: तुमचा संदर्भ क्रमांक लिहा, उदा. JN-2026-000123. स्थिती बदलल्यावर तुम्हाला ई-मेल येतो.', 'स्थिती, माझी तक्रार, कुठे आहे, काय झाले, ट्रॅक', 50),
('track-complaint', 'BN', 'TRACK', 'কীভাবে আমার অভিযোগের অবস্থা দেখব?', 'আমার অভিযোগ খুলুন, সেখানে প্রতিটি অভিযোগ ও তার বর্তমান অবস্থা দেখা যায়। পুরো ইতিহাস দেখতে একটি অভিযোগে ট্যাপ করুন। আপনি আমাকেও জিজ্ঞাসা করতে পারেন: আপনার রেফারেন্স নম্বর লিখুন, যেমন JN-2026-000123। অবস্থা বদলালে আপনি ই-মেল পাবেন।', 'অবস্থা, আমার অভিযোগ, কোথায়, কী হল, ট্র্যাক', 50),
('track-complaint', 'TA', 'TRACK', 'என் புகாரின் நிலையை எப்படிப் பார்ப்பது?', 'என் புகார்கள் திறக்கவும், ஒவ்வொரு புகாரும் அதன் தற்போதைய நிலையும் தெரியும். முழு வரலாற்றைப் பார்க்க ஒரு புகாரைத் தட்டவும். என்னிடமும் கேட்கலாம்: உங்கள் குறிப்பு எண்ணைத் தட்டச்சு செய்யவும், உதாரணமாக JN-2026-000123. நிலை மாறும்போது மின்னஞ்சல் வரும்.', 'நிலை, என் புகார், எங்கே, என்ன ஆனது, பின்தொடர்', 50),
('track-complaint', 'TE', 'TRACK', 'నా ఫిర్యాదు స్థితిని ఎలా చూడాలి?', 'నా ఫిర్యాదులు తెరవండి, అక్కడ ప్రతి ఫిర్యాదు, దాని ప్రస్తుత స్థితి కనిపిస్తాయి. పూర్తి చరిత్ర చూడటానికి ఒక ఫిర్యాదుపై నొక్కండి. నన్ను కూడా అడగవచ్చు: మీ రిఫరెన్స్ నంబర్ టైప్ చేయండి, ఉదాహరణకు JN-2026-000123. స్థితి మారినప్పుడు మీకు ఇ-మెయిల్ వస్తుంది.', 'స్థితి, నా ఫిర్యాదు, ఎక్కడ ఉంది, ఏమైంది, ట్రాక్', 50),
('track-complaint', 'KN', 'TRACK', 'ನನ್ನ ದೂರಿನ ಸ್ಥಿತಿಯನ್ನು ಹೇಗೆ ನೋಡುವುದು?', 'ನನ್ನ ದೂರುಗಳು ತೆರೆಯಿರಿ, ಅಲ್ಲಿ ಪ್ರತಿ ದೂರು ಮತ್ತು ಅದರ ಈಗಿನ ಸ್ಥಿತಿ ಕಾಣುತ್ತದೆ. ಪೂರ್ಣ ಇತಿಹಾಸ ನೋಡಲು ದೂರಿನ ಮೇಲೆ ಟ್ಯಾಪ್ ಮಾಡಿ. ನನ್ನನ್ನೂ ಕೇಳಬಹುದು: ನಿಮ್ಮ ಉಲ್ಲೇಖ ಸಂಖ್ಯೆ ಬರೆಯಿರಿ, ಉದಾ. JN-2026-000123. ಸ್ಥಿತಿ ಬದಲಾದಾಗ ನಿಮಗೆ ಇ-ಮೇಲ್ ಬರುತ್ತದೆ.', 'ಸ್ಥಿತಿ, ನನ್ನ ದೂರು, ಎಲ್ಲಿದೆ, ಏನಾಯಿತು, ಟ್ರ್ಯಾಕ್', 50),
('status-meanings', 'EN', 'TRACK', 'What do the statuses mean?', 'Submitted / Under Review: your photo is being checked. Verified: accepted and sent to the right department. Assigned: an officer is responsible. In Progress: work has started. Resolved: the officer says it is fixed, please confirm. Closed: finished. Rejected: not accepted (you can appeal once). Duplicate: the same problem was already reported.', 'status meaning, what does it mean, meaning of status, verified, assigned, in progress, resolved, closed, matlab, ka matlab, status ka matlab', 60),
('status-meanings', 'HI', 'TRACK', 'स्थितियों का क्या मतलब है?', 'जमा की गई / समीक्षा में: आपकी फ़ोटो की जाँच हो रही है। सत्यापित: स्वीकार होकर सही विभाग को भेजी गई। सौंपी गई: एक अधिकारी ज़िम्मेदार है। प्रगति में: काम शुरू हो गया है। सुलझाई गई: अधिकारी के अनुसार ठीक हो गया, कृपया पुष्टि करें। बंद: पूरा हुआ। अस्वीकृत: स्वीकार नहीं हुई (एक बार अपील कर सकते हैं)। डुप्लिकेट: यही समस्या पहले दर्ज हो चुकी है।', 'मतलब, स्थिति का मतलब, सत्यापित, सौंपी गई, प्रगति पर, सुलझाई गई, बंद, matlab, ka matlab, status ka matlab', 60),
('status-meanings', 'MR', 'TRACK', 'स्थितींचा अर्थ काय?', 'सादर केली / आढाव्यात: तुमचा फोटो तपासला जात आहे. पडताळले: स्वीकारून योग्य विभागाकडे पाठवली. नेमली: एक अधिकारी जबाबदार आहे. प्रगतीत: काम सुरू झाले आहे. निराकरण झाले: अधिकाऱ्यानुसार दुरुस्त झाले, कृपया पुष्टी करा. बंद: पूर्ण झाले. नाकारली: स्वीकारली नाही (एकदा अपील करता येते). डुप्लिकेट: हीच समस्या आधीच नोंदवली आहे.', 'अर्थ, स्थितीचा अर्थ, पडताळलेली, सोपवलेली, प्रगतीत, बंद', 60),
('status-meanings', 'BN', 'TRACK', 'অবস্থাগুলোর মানে কী?', 'জমা দেওয়া হয়েছে / পর্যালোচনায়: আপনার ছবি পরীক্ষা করা হচ্ছে। যাচাই হয়েছে: গ্রহণ করে সঠিক বিভাগে পাঠানো হয়েছে। নিযুক্ত: একজন আধিকারিক দায়িত্বে আছেন। চলমান: কাজ শুরু হয়েছে। সমাধান হয়েছে: আধিকারিকের মতে ঠিক হয়েছে, দয়া করে নিশ্চিত করুন। বন্ধ: শেষ। প্রত্যাখ্যাত: গৃহীত হয়নি (একবার আপিল করা যায়)। ডুপ্লিকেট: একই সমস্যা আগেই জানানো হয়েছে।', 'মানে, অবস্থার মানে, যাচাইকৃত, দায়িত্ব, চলছে, বন্ধ', 60),
('status-meanings', 'TA', 'TRACK', 'நிலைகளின் பொருள் என்ன?', 'சமர்ப்பிக்கப்பட்டது / மதிப்பாய்வில்: உங்கள் புகைப்படம் சரிபார்க்கப்படுகிறது. சரிபார்க்கப்பட்டது: ஏற்கப்பட்டு சரியான துறைக்கு அனுப்பப்பட்டது. ஒதுக்கப்பட்டது: ஒரு அதிகாரி பொறுப்பு. நடைபெற்று வருகிறது: வேலை தொடங்கியது. தீர்க்கப்பட்டது: அதிகாரியின்படி சரிசெய்யப்பட்டது, உறுதிப்படுத்தவும். மூடப்பட்டது: முடிந்தது. நிராகரிக்கப்பட்டது: ஏற்கப்படவில்லை (ஒருமுறை மேல்முறையீடு செய்யலாம்). நகல்: அதே பிரச்சினை ஏற்கனவே புகாரளிக்கப்பட்டது.', 'பொருள், நிலையின் பொருள், சரிபார்க்கப்பட்டது, ஒதுக்கப்பட்டது, நடைபெறுகிறது, மூடப்பட்டது', 60),
('status-meanings', 'TE', 'TRACK', 'స్థితుల అర్థం ఏమిటి?', 'సమర్పించబడింది / సమీక్షలో ఉంది: మీ ఫోటో తనిఖీ అవుతోంది. ధృవీకరించబడింది: అంగీకరించి సరైన విభాగానికి పంపబడింది. కేటాయించబడింది: ఒక అధికారి బాధ్యత వహిస్తున్నారు. పురోగతిలో ఉంది: పని ప్రారంభమైంది. పరిష్కరించబడింది: అధికారి ప్రకారం సరిచేయబడింది, దయచేసి నిర్ధారించండి. మూసివేయబడింది: పూర్తైంది. తిరస్కరించబడింది: అంగీకరించబడలేదు (ఒకసారి అప్పీల్ చేయవచ్చు). డూప్లికేట్: అదే సమస్య ఇప్పటికే నివేదించబడింది.', 'అర్థం, స్థితి అర్థం, ధృవీకరించబడింది, కేటాయించబడింది, పురోగతిలో, మూసివేయబడింది', 60),
('status-meanings', 'KN', 'TRACK', 'ಸ್ಥಿತಿಗಳ ಅರ್ಥವೇನು?', 'ಸಲ್ಲಿಸಲಾಗಿದೆ / ಪರಿಶೀಲನೆಯಲ್ಲಿದೆ: ನಿಮ್ಮ ಫೋಟೋ ಪರಿಶೀಲನೆಯಲ್ಲಿದೆ. ಪರಿಶೀಲಿಸಲಾಗಿದೆ: ಸ್ವೀಕರಿಸಿ ಸರಿಯಾದ ಇಲಾಖೆಗೆ ಕಳುಹಿಸಲಾಗಿದೆ. ನಿಯೋಜಿಸಲಾಗಿದೆ: ಒಬ್ಬ ಅಧಿಕಾರಿ ಜವಾಬ್ದಾರರು. ಪ್ರಗತಿಯಲ್ಲಿದೆ: ಕೆಲಸ ಆರಂಭವಾಗಿದೆ. ಪರಿಹರಿಸಲಾಗಿದೆ: ಅಧಿಕಾರಿಯ ಪ್ರಕಾರ ಸರಿಯಾಗಿದೆ, ದಯವಿಟ್ಟು ದೃಢೀಕರಿಸಿ. ಮುಚ್ಚಲಾಗಿದೆ: ಮುಗಿದಿದೆ. ತಿರಸ್ಕರಿಸಲಾಗಿದೆ: ಸ್ವೀಕರಿಸಲಾಗಿಲ್ಲ (ಒಮ್ಮೆ ಮೇಲ್ಮನವಿ ಸಲ್ಲಿಸಬಹುದು). ಡುಪ್ಲಿಕೇಟ್: ಅದೇ ಸಮಸ್ಯೆ ಈಗಾಗಲೇ ವರದಿಯಾಗಿದೆ.', 'ಅರ್ಥ, ಸ್ಥಿತಿಯ ಅರ್ಥ, ಪರಿಶೀಲಿಸಲಾಗಿದೆ, ನಿಯೋಜಿಸಲಾಗಿದೆ, ಪ್ರಗತಿಯಲ್ಲಿದೆ, ಮುಚ್ಚಲಾಗಿದೆ', 60),
('ai-check', 'EN', 'TRACK', 'How does the AI check my photo?', 'An AI model looks at your photo to find the type of problem. If it is at least 50% sure, the complaint is accepted automatically. Otherwise a person from the Verification Team checks it. The steps of the decision are shown on your complaint.', 'ai, artificial intelligence, ai check, automatic, verification team, confidence, machine, ai kaise', 70),
('ai-check', 'HI', 'TRACK', 'AI मेरी फ़ोटो की जाँच कैसे करता है?', 'एक AI मॉडल आपकी फ़ोटो देखकर समस्या का प्रकार पहचानता है। अगर वह कम से कम 50% निश्चित है, तो शिकायत अपने-आप स्वीकार हो जाती है। नहीं तो सत्यापन टीम का कोई व्यक्ति उसकी जाँच करता है। निर्णय के चरण आपकी शिकायत पर दिखाए जाते हैं।', 'एआई, ai, जाँच, अपने-आप, सत्यापन टीम, मशीन, ai kaise', 70),
('ai-check', 'MR', 'TRACK', 'AI माझा फोटो कसा तपासतो?', 'एक AI मॉडेल तुमचा फोटो पाहून समस्येचा प्रकार ओळखतो. तो किमान 50% खात्रीशीर असल्यास तक्रार आपोआप स्वीकारली जाते. अन्यथा पडताळणी पथकातील व्यक्ती ती तपासते. निर्णयाचे टप्पे तुमच्या तक्रारीवर दाखवले जातात.', 'एआय, ai, तपासणी, आपोआप, पडताळणी पथक', 70),
('ai-check', 'BN', 'TRACK', 'AI কীভাবে আমার ছবি যাচাই করে?', 'একটি AI মডেল আপনার ছবি দেখে সমস্যার ধরন চিনে নেয়। অন্তত 50% নিশ্চিত হলে অভিযোগটি স্বয়ংক্রিয়ভাবে গৃহীত হয়। না হলে যাচাই দলের একজন ব্যক্তি সেটি পরীক্ষা করেন। সিদ্ধান্তের ধাপগুলি আপনার অভিযোগে দেখানো হয়।', 'এআই, ai, যাচাই, স্বয়ংক্রিয়, যাচাই দল', 70),
('ai-check', 'TA', 'TRACK', 'AI என் புகைப்படத்தை எப்படிச் சரிபார்க்கிறது?', 'ஒரு AI மாதிரி உங்கள் புகைப்படத்தைப் பார்த்துப் பிரச்சினையின் வகையைக் கண்டறிகிறது. குறைந்தது 50% உறுதியாக இருந்தால் புகார் தானாக ஏற்கப்படும். இல்லையெனில் சரிபார்ப்புக் குழுவின் ஒருவர் அதைச் சரிபார்ப்பார். முடிவின் படிகள் உங்கள் புகாரில் காட்டப்படும்.', 'ஏஐ, ai, சரிபார்ப்பு, தானாக, சரிபார்ப்புக் குழு', 70),
('ai-check', 'TE', 'TRACK', 'AI నా ఫోటోను ఎలా తనిఖీ చేస్తుంది?', 'ఒక AI మోడల్ మీ ఫోటోను చూసి సమస్య రకాన్ని గుర్తిస్తుంది. కనీసం 50% నిశ్చయంగా ఉంటే ఫిర్యాదు స్వయంచాలకంగా అంగీకరించబడుతుంది. లేకపోతే ధృవీకరణ బృందంలోని వ్యక్తి దాన్ని తనిఖీ చేస్తారు. నిర్ణయం యొక్క దశలు మీ ఫిర్యాదుపై చూపబడతాయి.', 'ఏఐ, ai, తనిఖీ, స్వయంచాలకం, ధృవీకరణ బృందం', 70),
('ai-check', 'KN', 'TRACK', 'AI ನನ್ನ ಫೋಟೋವನ್ನು ಹೇಗೆ ಪರಿಶೀಲಿಸುತ್ತದೆ?', 'ಒಂದು AI ಮಾದರಿ ನಿಮ್ಮ ಫೋಟೋವನ್ನು ನೋಡಿ ಸಮಸ್ಯೆಯ ವಿಧವನ್ನು ಗುರುತಿಸುತ್ತದೆ. ಕನಿಷ್ಠ 50% ಖಚಿತವಾಗಿದ್ದರೆ ದೂರು ತಾನಾಗಿಯೇ ಸ್ವೀಕೃತವಾಗುತ್ತದೆ. ಇಲ್ಲದಿದ್ದರೆ ಪರಿಶೀಲನಾ ತಂಡದ ವ್ಯಕ್ತಿಯೊಬ್ಬರು ಅದನ್ನು ಪರಿಶೀಲಿಸುತ್ತಾರೆ. ನಿರ್ಧಾರದ ಹಂತಗಳನ್ನು ನಿಮ್ಮ ದೂರಿನಲ್ಲಿ ತೋರಿಸಲಾಗುತ್ತದೆ.', 'ಎಐ, ai, ಪರಿಶೀಲನೆ, ತಾನಾಗಿ, ಪರಿಶೀಲನಾ ತಂಡ', 70),
('who-handles', 'EN', 'TRACK', 'Which office handles my complaint?', 'The complaint goes to the department for that type of problem in your area: first the Gram Panchayat or town office, then the block, then the district. The department head assigns an officer. The department and the officer are shown on your complaint.', 'department, officer, which office, who will handle, who handles, office, kaun dekhega, vibhag, adhikari, kis vibhag', 80),
('who-handles', 'HI', 'TRACK', 'मेरी शिकायत कौन सा कार्यालय देखता है?', 'शिकायत आपके क्षेत्र में उस प्रकार की समस्या वाले विभाग को जाती है: पहले ग्राम पंचायत या नगर कार्यालय, फिर ब्लॉक, फिर ज़िला। विभाग प्रमुख एक अधिकारी को सौंपते हैं। विभाग और अधिकारी आपकी शिकायत पर दिखाए जाते हैं।', 'विभाग, अधिकारी, कौन देखेगा, कार्यालय, किस विभाग, kaun dekhega, vibhag, adhikari', 80),
('who-handles', 'MR', 'TRACK', 'माझी तक्रार कोणते कार्यालय पाहते?', 'तक्रार तुमच्या भागातील त्या प्रकारच्या समस्येच्या विभागाकडे जाते: आधी ग्रामपंचायत किंवा नगर कार्यालय, नंतर ब्लॉक, नंतर जिल्हा. विभाग प्रमुख एका अधिकाऱ्याकडे सोपवतात. विभाग आणि अधिकारी तुमच्या तक्रारीवर दाखवले जातात.', 'विभाग, अधिकारी, कोण पाहील, कार्यालय', 80),
('who-handles', 'BN', 'TRACK', 'কোন অফিস আমার অভিযোগ দেখে?', 'অভিযোগটি আপনার এলাকায় সেই ধরনের সমস্যার বিভাগে যায়: প্রথমে গ্রাম পঞ্চায়েত বা শহরের অফিস, তারপর ব্লক, তারপর জেলা। বিভাগীয় প্রধান একজন আধিকারিককে দায়িত্ব দেন। বিভাগ ও আধিকারিক আপনার অভিযোগে দেখানো হয়।', 'বিভাগ, আধিকারিক, কে দেখবে, অফিস', 80),
('who-handles', 'TA', 'TRACK', 'என் புகாரை எந்த அலுவலகம் கையாளுகிறது?', 'உங்கள் பகுதியில் அந்த வகைப் பிரச்சினைக்கான துறைக்குப் புகார் செல்லும்: முதலில் கிராம பஞ்சாயத்து அல்லது நகர அலுவலகம், பிறகு வட்டாரம், பிறகு மாவட்டம். துறைத் தலைவர் ஒரு அதிகாரியை நியமிப்பார். துறையும் அதிகாரியும் உங்கள் புகாரில் காட்டப்படும்.', 'துறை, அதிகாரி, யார் கையாளுவார், அலுவலகம்', 80),
('who-handles', 'TE', 'TRACK', 'నా ఫిర్యాదును ఏ కార్యాలయం చూస్తుంది?', 'మీ ప్రాంతంలో ఆ రకం సమస్యకు సంబంధించిన విభాగానికి ఫిర్యాదు వెళ్తుంది: ముందు గ్రామ పంచాయతీ లేదా పట్టణ కార్యాలయం, తర్వాత బ్లాక్, తర్వాత జిల్లా. విభాగాధిపతి ఒక అధికారిని కేటాయిస్తారు. విభాగం, అధికారి మీ ఫిర్యాదుపై చూపబడతారు.', 'విభాగం, అధికారి, ఎవరు చూస్తారు, కార్యాలయం', 80),
('who-handles', 'KN', 'TRACK', 'ನನ್ನ ದೂರನ್ನು ಯಾವ ಕಚೇರಿ ನೋಡುತ್ತದೆ?', 'ನಿಮ್ಮ ಪ್ರದೇಶದಲ್ಲಿ ಆ ರೀತಿಯ ಸಮಸ್ಯೆಯ ಇಲಾಖೆಗೆ ದೂರು ಹೋಗುತ್ತದೆ: ಮೊದಲು ಗ್ರಾಮ ಪಂಚಾಯಿತಿ ಅಥವಾ ಪಟ್ಟಣ ಕಚೇರಿ, ನಂತರ ಬ್ಲಾಕ್, ನಂತರ ಜಿಲ್ಲೆ. ಇಲಾಖೆಯ ಮುಖ್ಯಸ್ಥರು ಒಬ್ಬ ಅಧಿಕಾರಿಯನ್ನು ನಿಯೋಜಿಸುತ್ತಾರೆ. ಇಲಾಖೆ ಮತ್ತು ಅಧಿಕಾರಿಯನ್ನು ನಿಮ್ಮ ದೂರಿನಲ್ಲಿ ತೋರಿಸಲಾಗುತ್ತದೆ.', 'ಇಲಾಖೆ, ಅಧಿಕಾರಿ, ಯಾರು ನೋಡುತ್ತಾರೆ, ಕಚೇರಿ', 80),
('timelines', 'EN', 'TRACK', 'How long will it take?', 'Every department has a time limit (SLA) for each type of problem, counted from when the complaint is accepted. If the time limit is missed, the complaint is escalated automatically to a senior officer.', 'how long, how many days, when will, time limit, sla, deadline, delay, late, kitne din, kab tak, kab hoga, der', 90),
('timelines', 'HI', 'TRACK', 'कितना समय लगेगा?', 'हर विभाग की हर प्रकार की समस्या के लिए एक समय-सीमा (SLA) होती है, जो शिकायत स्वीकार होने से गिनी जाती है। समय-सीमा निकल जाने पर शिकायत अपने-आप वरिष्ठ अधिकारी के पास भेज दी जाती है।', 'कितना समय, कितने दिन, कब तक, कब होगा, देर, समय-सीमा, kitne din, kab tak, kab hoga, der', 90),
('timelines', 'MR', 'TRACK', 'किती वेळ लागेल?', 'प्रत्येक विभागाची प्रत्येक प्रकारच्या समस्येसाठी एक वेळमर्यादा (SLA) असते, जी तक्रार स्वीकारल्यापासून मोजली जाते. वेळमर्यादा ओलांडल्यास तक्रार आपोआप वरिष्ठ अधिकाऱ्याकडे पाठवली जाते.', 'किती वेळ, किती दिवस, केव्हा, उशीर, वेळमर्यादा', 90),
('timelines', 'BN', 'TRACK', 'কত সময় লাগবে?', 'প্রতিটি বিভাগের প্রতিটি ধরনের সমস্যার জন্য একটি সময়সীমা (SLA) থাকে, যা অভিযোগ গৃহীত হওয়ার সময় থেকে গোনা হয়। সময়সীমা পেরিয়ে গেলে অভিযোগটি স্বয়ংক্রিয়ভাবে ঊর্ধ্বতন আধিকারিকের কাছে পাঠানো হয়।', 'কত সময়, কত দিন, কবে, দেরি, সময়সীমা', 90),
('timelines', 'TA', 'TRACK', 'எவ்வளவு நேரம் ஆகும்?', 'ஒவ்வொரு துறைக்கும் ஒவ்வொரு வகைப் பிரச்சினைக்கும் ஒரு கால வரம்பு (SLA) உண்டு, அது புகார் ஏற்கப்பட்டதிலிருந்து கணக்கிடப்படும். கால வரம்பு தவறினால் புகார் தானாகவே மூத்த அதிகாரிக்கு அனுப்பப்படும்.', 'எவ்வளவு நேரம், எத்தனை நாள், எப்போது, தாமதம், கால வரம்பு', 90),
('timelines', 'TE', 'TRACK', 'ఎంత సమయం పడుతుంది?', 'ప్రతి విభాగానికి ప్రతి రకం సమస్యకు ఒక గడువు (SLA) ఉంటుంది, ఫిర్యాదు అంగీకరించిన సమయం నుండి లెక్కిస్తారు. గడువు దాటితే ఫిర్యాదు స్వయంచాలకంగా సీనియర్ అధికారికి పంపబడుతుంది.', 'ఎంత సమయం, ఎన్ని రోజులు, ఎప్పుడు, ఆలస్యం, గడువు', 90),
('timelines', 'KN', 'TRACK', 'ಎಷ್ಟು ಸಮಯ ಬೇಕಾಗುತ್ತದೆ?', 'ಪ್ರತಿ ಇಲಾಖೆಗೆ ಪ್ರತಿ ರೀತಿಯ ಸಮಸ್ಯೆಗೆ ಒಂದು ಸಮಯ ಮಿತಿ (SLA) ಇರುತ್ತದೆ, ದೂರು ಸ್ವೀಕರಿಸಿದಾಗಿನಿಂದ ಎಣಿಸಲಾಗುತ್ತದೆ. ಸಮಯ ಮಿತಿ ಮೀರಿದರೆ ದೂರು ತಾನಾಗಿಯೇ ಹಿರಿಯ ಅಧಿಕಾರಿಗೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ.', 'ಎಷ್ಟು ಸಮಯ, ಎಷ್ಟು ದಿನ, ಯಾವಾಗ, ತಡ, ಸಮಯ ಮಿತಿ', 90),
('escalation', 'EN', 'TRACK', 'What does escalated mean?', 'Escalated means the complaint was sent to a higher level because it was not handled within the time limit, or an officer asked for help. It stays with the same department and you can keep tracking it.', 'escalated, escalation, higher level, senior officer, upar bheja', 100),
('escalation', 'HI', 'TRACK', 'उच्च स्तर पर भेजी गई का क्या मतलब है?', 'इसका मतलब है कि शिकायत समय-सीमा में नहीं निपटी, या अधिकारी ने मदद माँगी, इसलिए उसे उच्च स्तर पर भेजा गया। शिकायत उसी विभाग में रहती है और आप उसे देखते रह सकते हैं।', 'उच्च स्तर, वरिष्ठ, एस्केलेट, ऊपर भेजी, upar bheja, escalate', 100),
('escalation', 'MR', 'TRACK', 'वरिष्ठांकडे पाठवली म्हणजे काय?', 'याचा अर्थ तक्रार वेळमर्यादेत हाताळली गेली नाही किंवा अधिकाऱ्याने मदत मागितली, म्हणून ती वरच्या स्तरावर पाठवली. ती त्याच विभागात राहते आणि तुम्ही ती पाहत राहू शकता.', 'वरिष्ठ, वरच्या स्तरावर, एस्केलेट', 100),
('escalation', 'BN', 'TRACK', 'উচ্চ স্তরে পাঠানো মানে কী?', 'এর মানে অভিযোগটি সময়সীমার মধ্যে নিষ্পত্তি হয়নি, অথবা আধিকারিক সাহায্য চেয়েছেন, তাই এটি উচ্চ স্তরে পাঠানো হয়েছে। অভিযোগটি একই বিভাগে থাকে এবং আপনি দেখতে থাকতে পারেন।', 'উচ্চ স্তর, ঊর্ধ্বতন, এসকেলেট', 100),
('escalation', 'TA', 'TRACK', 'உயர்நிலைக்கு அனுப்பப்பட்டது என்றால் என்ன?', 'கால வரம்பிற்குள் புகார் கையாளப்படவில்லை, அல்லது அதிகாரி உதவி கேட்டார், எனவே அது உயர்நிலைக்கு அனுப்பப்பட்டது என்று பொருள். அது அதே துறையில் இருக்கும், நீங்கள் தொடர்ந்து பின்தொடரலாம்.', 'உயர்நிலை, மூத்த அதிகாரி, எஸ்கலேட்', 100),
('escalation', 'TE', 'TRACK', 'ఉన్నత స్థాయికి పంపబడింది అంటే ఏమిటి?', 'ఫిర్యాదు గడువులోపు పరిష్కారం కాలేదు, లేదా అధికారి సహాయం అడిగారు, అందుకే అది ఉన్నత స్థాయికి పంపబడింది అని అర్థం. అది అదే విభాగంలో ఉంటుంది, మీరు ట్రాక్ చేస్తూ ఉండవచ్చు.', 'ఉన్నత స్థాయి, సీనియర్, ఎస్కలేట్', 100),
('escalation', 'KN', 'TRACK', 'ಹೆಚ್ಚಿನ ಹಂತಕ್ಕೆ ಕಳುಹಿಸಲಾಗಿದೆ ಎಂದರೆ ಏನು?', 'ದೂರು ಸಮಯ ಮಿತಿಯೊಳಗೆ ನಿರ್ವಹಿಸಲ್ಪಡಲಿಲ್ಲ, ಅಥವಾ ಅಧಿಕಾರಿ ಸಹಾಯ ಕೇಳಿದರು, ಆದ್ದರಿಂದ ಅದನ್ನು ಹೆಚ್ಚಿನ ಹಂತಕ್ಕೆ ಕಳುಹಿಸಲಾಗಿದೆ ಎಂದರ್ಥ. ಅದು ಅದೇ ಇಲಾಖೆಯಲ್ಲಿರುತ್ತದೆ, ನೀವು ಟ್ರ್ಯಾಕ್ ಮಾಡುತ್ತಲೇ ಇರಬಹುದು.', 'ಹೆಚ್ಚಿನ ಹಂತ, ಹಿರಿಯ ಅಧಿಕಾರಿ, ಎಸ್ಕಲೇಟ್', 100),
('resolved-confirm', 'EN', 'AFTER', 'My complaint is resolved. What now?', 'When an officer marks your complaint Resolved, they upload a photo of the work. Check it and press Confirm if the problem is fixed; the complaint is then Closed. If you do nothing, it closes automatically after the confirmation period (3 days unless the Admin changed it).', 'resolved, confirm, fixed, work done, close complaint, confirmation, theek ho gaya, kaam ho gaya, confirm kaise', 110),
('resolved-confirm', 'HI', 'AFTER', 'मेरी शिकायत सुलझ गई है, अब क्या करूँ?', 'जब अधिकारी शिकायत को सुलझाई गई चिह्नित करते हैं, तो वे काम की फ़ोटो अपलोड करते हैं। उसे देखें और समस्या ठीक हो गई हो तो पुष्टि करें दबाएँ; तब शिकायत बंद हो जाती है। कुछ न करने पर पुष्टि अवधि (जब तक एडमिन ने न बदला हो, 3 दिन) के बाद वह अपने-आप बंद हो जाती है।', 'सुलझ गई, पुष्टि, ठीक हो गया, काम हो गया, बंद करें, theek ho gaya, kaam ho gaya, confirm kaise', 110),
('resolved-confirm', 'MR', 'AFTER', 'माझी तक्रार निराकरण झाली, आता काय?', 'अधिकारी तक्रार निराकरण झाली म्हणून चिन्हांकित करताना कामाचा फोटो अपलोड करतात. तो तपासा आणि समस्या दुरुस्त झाली असल्यास पुष्टी करा दाबा; मग तक्रार बंद होते. काहीही न केल्यास पुष्टी कालावधीनंतर (प्रशासकाने बदलला नसल्यास 3 दिवस) ती आपोआप बंद होते.', 'निराकरण, पुष्टी, दुरुस्त झाले, काम झाले, बंद', 110),
('resolved-confirm', 'BN', 'AFTER', 'আমার অভিযোগের সমাধান হয়েছে, এখন কী করব?', 'আধিকারিক অভিযোগটি সমাধান হয়েছে চিহ্নিত করার সময় কাজের ছবি আপলোড করেন। সেটি দেখুন এবং সমস্যা ঠিক হলে নিশ্চিত করুন চাপুন; তখন অভিযোগ বন্ধ হয়। কিছু না করলে নিশ্চিতকরণ সময়ের পরে (অ্যাডমিন না বদলালে 3 দিন) এটি স্বয়ংক্রিয়ভাবে বন্ধ হয়।', 'সমাধান, নিশ্চিত, ঠিক হয়েছে, কাজ হয়েছে, বন্ধ', 110),
('resolved-confirm', 'TA', 'AFTER', 'என் புகார் தீர்க்கப்பட்டது, இப்போது என்ன?', 'அதிகாரி புகாரைத் தீர்க்கப்பட்டது எனக் குறிக்கும்போது வேலையின் புகைப்படத்தைப் பதிவேற்றுவார். அதைப் பார்த்து, பிரச்சினை சரியாகியிருந்தால் உறுதிப்படுத்து அழுத்தவும்; அப்போது புகார் மூடப்படும். எதுவும் செய்யாவிட்டால் உறுதிப்படுத்தும் காலத்திற்குப் பின் (நிர்வாகி மாற்றாவிட்டால் 3 நாட்கள்) தானாக மூடப்படும்.', 'தீர்க்கப்பட்டது, உறுதிப்படுத்து, சரியானது, வேலை முடிந்தது, மூடு', 110),
('resolved-confirm', 'TE', 'AFTER', 'నా ఫిర్యాదు పరిష్కరించబడింది, ఇప్పుడు ఏమి చేయాలి?', 'అధికారి ఫిర్యాదును పరిష్కరించబడింది అని గుర్తించేటప్పుడు పని ఫోటోను అప్‌లోడ్ చేస్తారు. దాన్ని చూసి, సమస్య సరైతే నిర్ధారించు నొక్కండి; అప్పుడు ఫిర్యాదు మూసివేయబడుతుంది. ఏమీ చేయకపోతే నిర్ధారణ వ్యవధి తర్వాత (అడ్మిన్ మార్చకపోతే 3 రోజులు) స్వయంచాలకంగా మూసివేయబడుతుంది.', 'పరిష్కరించబడింది, నిర్ధారించు, సరైంది, పని పూర్తైంది, మూసివేయి', 110),
('resolved-confirm', 'KN', 'AFTER', 'ನನ್ನ ದೂರು ಪರಿಹಾರವಾಗಿದೆ, ಈಗ ಏನು?', 'ಅಧಿಕಾರಿ ದೂರನ್ನು ಪರಿಹರಿಸಲಾಗಿದೆ ಎಂದು ಗುರುತಿಸುವಾಗ ಕೆಲಸದ ಫೋಟೋ ಅಪ್‌ಲೋಡ್ ಮಾಡುತ್ತಾರೆ. ಅದನ್ನು ನೋಡಿ, ಸಮಸ್ಯೆ ಸರಿಯಾಗಿದ್ದರೆ ದೃಢೀಕರಿಸಿ ಒತ್ತಿರಿ; ಆಗ ದೂರು ಮುಚ್ಚಲ್ಪಡುತ್ತದೆ. ಏನೂ ಮಾಡದಿದ್ದರೆ ದೃಢೀಕರಣ ಅವಧಿಯ ನಂತರ (ನಿರ್ವಾಹಕರು ಬದಲಾಯಿಸದಿದ್ದರೆ 3 ದಿನ) ತಾನಾಗಿಯೇ ಮುಚ್ಚಲ್ಪಡುತ್ತದೆ.', 'ಪರಿಹರಿಸಲಾಗಿದೆ, ದೃಢೀಕರಿಸಿ, ಸರಿಯಾಗಿದೆ, ಕೆಲಸ ಮುಗಿದಿದೆ, ಮುಚ್ಚು', 110),
('reopen', 'EN', 'AFTER', 'The problem is not fixed. Can I reopen it?', 'Yes. While the complaint is Resolved and the confirmation period is running, open it, press Reopen and say what is still wrong. It goes back to the department. After the period ends it cannot be reopened; report the problem again as a new complaint.', 'reopen, not fixed, still not fixed, problem again, not done, dobara, phir se, theek nahi hua, kaam nahi hua, reopen kaise', 120),
('reopen', 'HI', 'AFTER', 'समस्या ठीक नहीं हुई, क्या दोबारा खोल सकते हैं?', 'हाँ। जब तक शिकायत सुलझाई गई स्थिति में है और पुष्टि अवधि चल रही है, उसे खोलें, दोबारा खोलें दबाएँ और बताएँ कि क्या ठीक नहीं हुआ। शिकायत वापस विभाग को जाती है। अवधि ख़त्म होने के बाद उसे दोबारा नहीं खोला जा सकता; तब समस्या को नई शिकायत के रूप में दर्ज करें।', 'दोबारा खोलें, ठीक नहीं हुआ, काम नहीं हुआ, फिर से, dobara, phir se, theek nahi hua, kaam nahi hua', 120),
('reopen', 'MR', 'AFTER', 'समस्या दुरुस्त झाली नाही, पुन्हा उघडता येईल का?', 'होय. तक्रार निराकरण झाली स्थितीत असताना आणि पुष्टी कालावधी सुरू असताना, ती उघडा, पुन्हा उघडा दाबा आणि काय अजूनही चुकीचे आहे ते सांगा. ती पुन्हा विभागाकडे जाते. कालावधी संपल्यानंतर ती पुन्हा उघडता येत नाही; समस्या नवीन तक्रार म्हणून नोंदवा.', 'पुन्हा उघडा, दुरुस्त झाले नाही, काम झाले नाही, पुन्हा', 120),
('reopen', 'BN', 'AFTER', 'সমস্যা ঠিক হয়নি, আবার খোলা যাবে?', 'হ্যাঁ। অভিযোগটি সমাধান হয়েছে অবস্থায় থাকাকালীন এবং নিশ্চিতকরণ সময় চলাকালীন, সেটি খুলুন, আবার খুলুন চাপুন এবং কী এখনও ঠিক হয়নি তা লিখুন। এটি আবার বিভাগে যায়। সময় শেষ হলে আর খোলা যায় না; সমস্যাটি নতুন অভিযোগ হিসেবে জানান।', 'আবার খুলুন, ঠিক হয়নি, কাজ হয়নি, আবার', 120),
('reopen', 'TA', 'AFTER', 'பிரச்சினை சரியாகவில்லை, மீண்டும் திறக்கலாமா?', 'ஆம். புகார் தீர்க்கப்பட்டது நிலையில் இருக்கும்போதும் உறுதிப்படுத்தும் காலம் நடைபெறும்போதும், அதைத் திறந்து மீண்டும் திற அழுத்தி, இன்னும் என்ன சரியில்லை என்று சொல்லவும். அது மீண்டும் துறைக்குச் செல்லும். காலம் முடிந்த பின் மீண்டும் திறக்க முடியாது; பிரச்சினையைப் புதிய புகாராகப் பதிவு செய்யவும்.', 'மீண்டும் திற, சரியாகவில்லை, வேலை முடியவில்லை, மீண்டும்', 120),
('reopen', 'TE', 'AFTER', 'సమస్య సరి కాలేదు, మళ్లీ తెరవవచ్చా?', 'అవును. ఫిర్యాదు పరిష్కరించబడింది స్థితిలో ఉండి నిర్ధారణ వ్యవధి నడుస్తున్నప్పుడు, దాన్ని తెరిచి మళ్లీ తెరువు నొక్కి, ఇంకా ఏమి సరిగా లేదో చెప్పండి. అది తిరిగి విభాగానికి వెళ్తుంది. వ్యవధి ముగిసిన తర్వాత మళ్లీ తెరవలేరు; సమస్యను కొత్త ఫిర్యాదుగా నివేదించండి.', 'మళ్లీ తెరువు, సరి కాలేదు, పని కాలేదు, మళ్లీ', 120),
('reopen', 'KN', 'AFTER', 'ಸಮಸ್ಯೆ ಸರಿಯಾಗಿಲ್ಲ, ಮತ್ತೆ ತೆರೆಯಬಹುದೇ?', 'ಹೌದು. ದೂರು ಪರಿಹರಿಸಲಾಗಿದೆ ಸ್ಥಿತಿಯಲ್ಲಿದ್ದು ದೃಢೀಕರಣ ಅವಧಿ ನಡೆಯುತ್ತಿರುವಾಗ, ಅದನ್ನು ತೆರೆದು ಮತ್ತೆ ತೆರೆಯಿರಿ ಒತ್ತಿ, ಇನ್ನೂ ಏನು ಸರಿಯಿಲ್ಲ ಎಂದು ತಿಳಿಸಿ. ಅದು ಮತ್ತೆ ಇಲಾಖೆಗೆ ಹೋಗುತ್ತದೆ. ಅವಧಿ ಮುಗಿದ ನಂತರ ಮತ್ತೆ ತೆರೆಯಲಾಗುವುದಿಲ್ಲ; ಸಮಸ್ಯೆಯನ್ನು ಹೊಸ ದೂರಾಗಿ ವರದಿ ಮಾಡಿ.', 'ಮತ್ತೆ ತೆರೆಯಿರಿ, ಸರಿಯಾಗಿಲ್ಲ, ಕೆಲಸ ಆಗಿಲ್ಲ, ಮತ್ತೆ', 120),
('rejected-why', 'EN', 'AFTER', 'Why was my complaint rejected?', 'A rejection always has a reason: not a civic issue, duplicate submission, not enough evidence (the photo does not show the problem), outside the jurisdiction, or spam or abuse. The reason is shown on your complaint. If you think it is wrong, you can appeal once.', 'rejected, rejection, why rejected, reason, not accepted, reject kyu, kyon reject, reject kyun hua, mana kar diya', 130),
('rejected-why', 'HI', 'AFTER', 'मेरी शिकायत अस्वीकार क्यों हुई?', 'अस्वीकृति का हमेशा एक कारण होता है: नागरिक समस्या नहीं, दोहराई गई शिकायत, पर्याप्त सबूत नहीं (फ़ोटो में समस्या नहीं दिखती), क्षेत्राधिकार से बाहर, या स्पैम / दुरुपयोग। कारण आपकी शिकायत पर दिखाया जाता है। अगर आपको लगता है कि यह ग़लत है, तो आप एक बार अपील कर सकते हैं।', 'अस्वीकार, अस्वीकृत, क्यों, कारण, रिजेक्ट, reject kyu, kyon reject, reject kyun hua, mana kar diya', 130),
('rejected-why', 'MR', 'AFTER', 'माझी तक्रार का नाकारली?', 'नाकारण्याचे नेहमी एक कारण असते: नागरी समस्या नाही, पुन्हा नोंदवलेली तक्रार, पुरेसा पुरावा नाही (फोटोत समस्या दिसत नाही), अधिकारक्षेत्राबाहेर, किंवा स्पॅम / गैरवापर. कारण तुमच्या तक्रारीवर दाखवले जाते. ते चुकीचे वाटल्यास तुम्ही एकदा अपील करू शकता.', 'नाकारली, का, कारण, रिजेक्ट', 130),
('rejected-why', 'BN', 'AFTER', 'আমার অভিযোগ কেন প্রত্যাখ্যাত হল?', 'প্রত্যাখ্যানের সবসময় একটি কারণ থাকে: নাগরিক সমস্যা নয়, একই অভিযোগ আবার জমা, যথেষ্ট প্রমাণ নেই (ছবিতে সমস্যা দেখা যায় না), এক্তিয়ারের বাইরে, অথবা স্প্যাম / অপব্যবহার। কারণটি আপনার অভিযোগে দেখানো হয়। ভুল মনে হলে আপনি একবার আপিল করতে পারেন।', 'প্রত্যাখ্যাত, কেন, কারণ, রিজেক্ট', 130),
('rejected-why', 'TA', 'AFTER', 'என் புகார் ஏன் நிராகரிக்கப்பட்டது?', 'நிராகரிப்புக்கு எப்போதும் ஒரு காரணம் உண்டு: குடிமைப் பிரச்சினை அல்ல, மீண்டும் சமர்ப்பித்த புகார், போதுமான ஆதாரம் இல்லை (புகைப்படத்தில் பிரச்சினை தெரியவில்லை), அதிகார வரம்புக்கு வெளியே, அல்லது ஸ்பேம் / தவறான பயன்பாடு. காரணம் உங்கள் புகாரில் காட்டப்படும். தவறு என்று நினைத்தால் ஒருமுறை மேல்முறையீடு செய்யலாம்.', 'நிராகரிக்கப்பட்டது, ஏன், காரணம், ரிஜெக்ட்', 130),
('rejected-why', 'TE', 'AFTER', 'నా ఫిర్యాదు ఎందుకు తిరస్కరించబడింది?', 'తిరస్కరణకు ఎప్పుడూ ఒక కారణం ఉంటుంది: పౌర సమస్య కాదు, మళ్లీ సమర్పించిన ఫిర్యాదు, తగిన ఆధారం లేదు (ఫోటోలో సమస్య కనిపించదు), పరిధి బయట, లేదా స్పామ్ / దుర్వినియోగం. కారణం మీ ఫిర్యాదుపై చూపబడుతుంది. తప్పు అనిపిస్తే ఒకసారి అప్పీల్ చేయవచ్చు.', 'తిరస్కరించబడింది, ఎందుకు, కారణం, రిజెక్ట్', 130),
('rejected-why', 'KN', 'AFTER', 'ನನ್ನ ದೂರು ಏಕೆ ತಿರಸ್ಕರಿಸಲಾಯಿತು?', 'ತಿರಸ್ಕಾರಕ್ಕೆ ಯಾವಾಗಲೂ ಒಂದು ಕಾರಣ ಇರುತ್ತದೆ: ನಾಗರಿಕ ಸಮಸ್ಯೆಯಲ್ಲ, ಮತ್ತೆ ಸಲ್ಲಿಸಿದ ದೂರು, ಸಾಕಷ್ಟು ಪುರಾವೆ ಇಲ್ಲ (ಫೋಟೋದಲ್ಲಿ ಸಮಸ್ಯೆ ಕಾಣುವುದಿಲ್ಲ), ವ್ಯಾಪ್ತಿಯ ಹೊರಗೆ, ಅಥವಾ ಸ್ಪ್ಯಾಮ್ / ದುರುಪಯೋಗ. ಕಾರಣವನ್ನು ನಿಮ್ಮ ದೂರಿನಲ್ಲಿ ತೋರಿಸಲಾಗುತ್ತದೆ. ತಪ್ಪು ಎನಿಸಿದರೆ ಒಮ್ಮೆ ಮೇಲ್ಮನವಿ ಸಲ್ಲಿಸಬಹುದು.', 'ತಿರಸ್ಕರಿಸಲಾಗಿದೆ, ಏಕೆ, ಕಾರಣ, ರಿಜೆಕ್ಟ್', 130),
('appeal', 'EN', 'AFTER', 'How do I appeal a rejection?', 'Open the rejected complaint, press Appeal Rejection and explain why it should be accepted. A complaint can be appealed only once. If the appeal is approved, the complaint is checked again; if it is rejected again, that decision is final.', 'appeal, how to appeal, challenge, wrong decision, apeel, appeal kaise, appeal karna', 140),
('appeal', 'HI', 'AFTER', 'अस्वीकृति के ख़िलाफ़ अपील कैसे करें?', 'अस्वीकृत शिकायत खोलें, अपील दबाएँ और बताएँ कि उसे क्यों स्वीकार किया जाना चाहिए। एक शिकायत पर केवल एक बार अपील हो सकती है। अपील मंज़ूर होने पर शिकायत की फिर से जाँच होती है; दोबारा अस्वीकार होने पर वह निर्णय अंतिम है।', 'अपील, अपील कैसे, ग़लत निर्णय, चुनौती, apeel, appeal kaise, appeal karna', 140),
('appeal', 'MR', 'AFTER', 'नाकारण्याविरुद्ध अपील कसे करावे?', 'नाकारलेली तक्रार उघडा, अपील दाबा आणि ती का स्वीकारावी ते सांगा. एका तक्रारीवर फक्त एकदाच अपील करता येते. अपील मंजूर झाल्यास तक्रार पुन्हा तपासली जाते; पुन्हा नाकारल्यास तो निर्णय अंतिम असतो.', 'अपील, अपील कसे, चुकीचा निर्णय', 140),
('appeal', 'BN', 'AFTER', 'প্রত্যাখ্যানের বিরুদ্ধে কীভাবে আপিল করব?', 'প্রত্যাখ্যাত অভিযোগটি খুলুন, আপিল চাপুন এবং কেন এটি গ্রহণ করা উচিত তা লিখুন। একটি অভিযোগে মাত্র একবার আপিল করা যায়। আপিল মঞ্জুর হলে অভিযোগটি আবার পরীক্ষা করা হয়; আবার প্রত্যাখ্যাত হলে সেই সিদ্ধান্ত চূড়ান্ত।', 'আপিল, কীভাবে আপিল, ভুল সিদ্ধান্ত', 140),
('appeal', 'TA', 'AFTER', 'நிராகரிப்புக்கு எதிராக எப்படி மேல்முறையீடு செய்வது?', 'நிராகரிக்கப்பட்ட புகாரைத் திறந்து மேல்முறையீடு அழுத்தி, அது ஏன் ஏற்கப்பட வேண்டும் என்று விளக்கவும். ஒரு புகாருக்கு ஒருமுறை மட்டுமே மேல்முறையீடு செய்ய முடியும். மேல்முறையீடு ஏற்கப்பட்டால் புகார் மீண்டும் சரிபார்க்கப்படும்; மீண்டும் நிராகரிக்கப்பட்டால் அந்த முடிவே இறுதியானது.', 'மேல்முறையீடு, எப்படி மேல்முறையீடு, தவறான முடிவு', 140),
('appeal', 'TE', 'AFTER', 'తిరస్కరణపై అప్పీల్ ఎలా చేయాలి?', 'తిరస్కరించిన ఫిర్యాదును తెరిచి, అప్పీల్ నొక్కి, దాన్ని ఎందుకు అంగీకరించాలో వివరించండి. ఒక ఫిర్యాదుపై ఒకసారి మాత్రమే అప్పీల్ చేయవచ్చు. అప్పీల్ ఆమోదిస్తే ఫిర్యాదు మళ్లీ తనిఖీ చేయబడుతుంది; మళ్లీ తిరస్కరిస్తే ఆ నిర్ణయమే తుది.', 'అప్పీల్, అప్పీల్ ఎలా, తప్పు నిర్ణయం', 140),
('appeal', 'KN', 'AFTER', 'ತಿರಸ್ಕಾರದ ವಿರುದ್ಧ ಮೇಲ್ಮನವಿ ಹೇಗೆ?', 'ತಿರಸ್ಕರಿಸಿದ ದೂರನ್ನು ತೆರೆದು, ಮೇಲ್ಮನವಿ ಒತ್ತಿ, ಅದನ್ನು ಏಕೆ ಸ್ವೀಕರಿಸಬೇಕು ಎಂದು ವಿವರಿಸಿ. ಒಂದು ದೂರಿಗೆ ಒಮ್ಮೆ ಮಾತ್ರ ಮೇಲ್ಮನವಿ ಸಲ್ಲಿಸಬಹುದು. ಮೇಲ್ಮನವಿ ಅನುಮೋದನೆಯಾದರೆ ದೂರನ್ನು ಮತ್ತೆ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ; ಮತ್ತೆ ತಿರಸ್ಕರಿಸಿದರೆ ಆ ನಿರ್ಧಾರವೇ ಅಂತಿಮ.', 'ಮೇಲ್ಮನವಿ, ಮೇಲ್ಮನವಿ ಹೇಗೆ, ತಪ್ಪು ನಿರ್ಧಾರ', 140),
('duplicate', 'EN', 'AFTER', 'What is a duplicate complaint?', 'If someone already reported the same problem nearby recently, your complaint is joined to that one instead of being handled twice. Your report still counts: it shows the department that more people are affected.', 'duplicate, same problem, already reported, merged, someone else reported, pehle se, duplicate kyu', 150),
('duplicate', 'HI', 'AFTER', 'डुप्लिकेट शिकायत क्या है?', 'अगर किसी ने हाल ही में पास में यही समस्या दर्ज की है, तो आपकी शिकायत को दो बार निपटाने के बजाय उसी से जोड़ दिया जाता है। आपकी शिकायत फिर भी गिनी जाती है: इससे विभाग को पता चलता है कि ज़्यादा लोग प्रभावित हैं।', 'डुप्लिकेट, वही समस्या, पहले से दर्ज, जोड़ दी, pehle se, duplicate kyu', 150),
('duplicate', 'MR', 'AFTER', 'डुप्लिकेट तक्रार म्हणजे काय?', 'कोणी अलीकडेच जवळपास हीच समस्या नोंदवली असल्यास, तुमची तक्रार दोनदा हाताळण्याऐवजी त्याच तक्रारीला जोडली जाते. तुमची तक्रार तरीही मोजली जाते: त्यामुळे विभागाला अधिक लोक प्रभावित असल्याचे कळते.', 'डुप्लिकेट, तीच समस्या, आधीच नोंदवली', 150),
('duplicate', 'BN', 'AFTER', 'ডুপ্লিকেট অভিযোগ কী?', 'সম্প্রতি কাছাকাছি কেউ একই সমস্যা জানিয়ে থাকলে, আপনার অভিযোগ দুবার না দেখে সেটির সঙ্গে যুক্ত করা হয়। আপনার অভিযোগ তবুও গোনা হয়: এতে বিভাগ জানে যে আরও বেশি মানুষ ক্ষতিগ্রস্ত।', 'ডুপ্লিকেট, একই সমস্যা, আগেই জানানো', 150),
('duplicate', 'TA', 'AFTER', 'நகல் புகார் என்றால் என்ன?', 'சமீபத்தில் அருகில் யாராவது அதே பிரச்சினையைப் புகாரளித்திருந்தால், உங்கள் புகார் இரண்டு முறை கையாளப்படாமல் அதனுடன் இணைக்கப்படும். உங்கள் புகார் அப்போதும் கணக்கில் வரும்: அதிகமானோர் பாதிக்கப்பட்டுள்ளனர் என்று துறைக்குத் தெரியும்.', 'நகல், அதே பிரச்சினை, ஏற்கனவே புகாரளிக்கப்பட்டது', 150),
('duplicate', 'TE', 'AFTER', 'నకిలీ ఫిర్యాదు అంటే ఏమిటి?', 'ఇటీవల సమీపంలో ఎవరైనా అదే సమస్యను నివేదించి ఉంటే, మీ ఫిర్యాదును రెండుసార్లు చూడకుండా దానితో కలుపుతారు. మీ ఫిర్యాదు అయినా లెక్కలోకి వస్తుంది: ఎక్కువ మంది ప్రభావితులయ్యారని విభాగానికి తెలుస్తుంది.', 'నకిలీ, అదే సమస్య, ఇప్పటికే నివేదించబడింది', 150),
('duplicate', 'KN', 'AFTER', 'ನಕಲು ದೂರು ಎಂದರೇನು?', 'ಇತ್ತೀಚೆಗೆ ಹತ್ತಿರದಲ್ಲಿ ಯಾರಾದರೂ ಅದೇ ಸಮಸ್ಯೆಯನ್ನು ವರದಿ ಮಾಡಿದ್ದರೆ, ನಿಮ್ಮ ದೂರನ್ನು ಎರಡು ಬಾರಿ ನಿರ್ವಹಿಸುವ ಬದಲು ಅದಕ್ಕೆ ಸೇರಿಸಲಾಗುತ್ತದೆ. ನಿಮ್ಮ ದೂರು ಆದರೂ ಎಣಿಕೆಯಾಗುತ್ತದೆ: ಹೆಚ್ಚು ಜನರು ಬಾಧಿತರಾಗಿದ್ದಾರೆ ಎಂದು ಇಲಾಖೆಗೆ ತಿಳಿಯುತ್ತದೆ.', 'ನಕಲು, ಅದೇ ಸಮಸ್ಯೆ, ಈಗಾಗಲೇ ವರದಿಯಾಗಿದೆ', 150),
('rating', 'EN', 'AFTER', 'Rating the work', 'After your complaint is closed you can rate how it was handled, from 1 to 5 stars, with an optional comment. Ratings help the government see which departments work well.', 'rate, rating, stars, feedback, review, rating kaise', 160),
('rating', 'HI', 'AFTER', 'काम को रेटिंग देना', 'शिकायत बंद होने के बाद आप 1 से 5 स्टार देकर बता सकते हैं कि उसे कैसे निपटाया गया, साथ में टिप्पणी भी लिख सकते हैं। रेटिंग से सरकार को पता चलता है कि कौन से विभाग अच्छा काम कर रहे हैं।', 'रेटिंग, स्टार, प्रतिक्रिया, फ़ीडबैक, rating kaise', 160),
('rating', 'MR', 'AFTER', 'कामाला रेटिंग देणे', 'तक्रार बंद झाल्यानंतर तुम्ही 1 ते 5 स्टार देऊन ती कशी हाताळली ते सांगू शकता, सोबत टिप्पणीही लिहू शकता. रेटिंगमुळे सरकारला कोणते विभाग चांगले काम करतात ते कळते.', 'रेटिंग, स्टार, अभिप्राय', 160),
('rating', 'BN', 'AFTER', 'কাজের রেটিং দেওয়া', 'অভিযোগ বন্ধ হওয়ার পরে আপনি 1 থেকে 5 তারা দিয়ে জানাতে পারেন এটি কীভাবে দেখা হয়েছে, সঙ্গে মন্তব্যও লিখতে পারেন। রেটিং থেকে সরকার জানতে পারে কোন বিভাগ ভালো কাজ করছে।', 'রেটিং, তারা, মতামত', 160),
('rating', 'TA', 'AFTER', 'வேலைக்கு மதிப்பீடு வழங்குதல்', 'புகார் மூடப்பட்ட பின், அது எப்படிக் கையாளப்பட்டது என்பதற்கு 1 முதல் 5 நட்சத்திரங்கள் வரை மதிப்பிடலாம், விருப்பப்பட்டால் கருத்தும் எழுதலாம். எந்தத் துறைகள் நன்றாக வேலை செய்கின்றன என்பதை அரசு அறிய மதிப்பீடுகள் உதவும்.', 'மதிப்பீடு, நட்சத்திரம், கருத்து', 160),
('rating', 'TE', 'AFTER', 'పనికి రేటింగ్ ఇవ్వడం', 'ఫిర్యాదు మూసివేయబడిన తర్వాత, అది ఎలా పరిష్కరించబడిందో 1 నుండి 5 నక్షత్రాలతో రేట్ చేయవచ్చు, కావాలంటే వ్యాఖ్య కూడా రాయవచ్చు. ఏ విభాగాలు బాగా పని చేస్తున్నాయో ప్రభుత్వానికి తెలియడానికి రేటింగ్‌లు సహాయపడతాయి.', 'రేటింగ్, నక్షత్రాలు, అభిప్రాయం', 160),
('rating', 'KN', 'AFTER', 'ಕೆಲಸಕ್ಕೆ ರೇಟಿಂಗ್ ನೀಡುವುದು', 'ದೂರು ಮುಚ್ಚಿದ ನಂತರ, ಅದನ್ನು ಹೇಗೆ ನಿರ್ವಹಿಸಲಾಯಿತು ಎಂಬುದಕ್ಕೆ 1 ರಿಂದ 5 ನಕ್ಷತ್ರಗಳವರೆಗೆ ರೇಟಿಂಗ್ ನೀಡಬಹುದು, ಬೇಕಿದ್ದರೆ ಟಿಪ್ಪಣಿಯನ್ನೂ ಬರೆಯಬಹುದು. ಯಾವ ಇಲಾಖೆಗಳು ಚೆನ್ನಾಗಿ ಕೆಲಸ ಮಾಡುತ್ತಿವೆ ಎಂದು ಸರ್ಕಾರಕ್ಕೆ ತಿಳಿಯಲು ರೇಟಿಂಗ್‌ಗಳು ಸಹಾಯ ಮಾಡುತ್ತವೆ.', 'ರೇಟಿಂಗ್, ನಕ್ಷತ್ರ, ಅಭಿಪ್ರಾಯ', 160),
